import {ZENIX_MAX_ENERGY} from './defib-guide.js';
import {ages,weights,medications,energies,protocol,pediatricTubes,igelForWeight,igelSource} from './data.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const routeBadges=route=>`<div class="critical-route" aria-label="Route: ${esc(route)}">${route.split('/').map(r=>`<span class="critical-route-badge">${esc(r.trim().toUpperCase())}</span>`).join('<span class="critical-route-divider" aria-hidden="true">/</span>')}</div>`;
const find=(name,route,concentration)=>medications.find(m=>m.name===name&&(!route||m.route===route)&&(!concentration||m.concentration===concentration));
export const criticalGroups=[
 {title:'Fluids',color:'blue',rows:[find('Normal saline bolus')],refs:[['FLUIDS · P613',169]],note:'20 mL/kg NS bolus · reassess after each bolus.'},
 {title:'Amio',color:'purple',rows:[find('Amiodarone · cardiac arrest')],refs:[['ARREST · P601',152]]},
 {title:'Lidocaine · IO',color:'teal',rows:[find('Lidocaine · before IO infusion')],refs:[['IO · T711',201]],note:'Prime extension tubing with lidocaine, not saline. Let dwell 60 seconds before the saline flush. Preservative-free, epinephrine-free 2%. N/A means no App J entry, not an age contraindication.',extraNote:'Small-dose exception: below 20 mg (1 mL), consider dosing directly at the catheter hub, then use a saline-primed extension per device instructions.',deviceLink:'https://www.teleflex.com/global/clinical-resources/documents/EZ-IO_Science_Fundamentals_MC-003266-Rev1-1.pdf#page=66'},
 {title:'Epi · all three kinds',color:'red',rows:[find('Epinephrine · cardiac arrest'),find('Epinephrine · anaphylaxis'),find('Epinephrine · push dose')],refs:[['ARREST · P601',152],['ANAPHYLAXIS · P609',163],['PUSH DOSE · SB205',54]]},
 {title:'Versed',color:'blue',rows:[find('Midazolam · seizures','IM/IN/Buccal'),find('Midazolam · seizures','IV'),find('Midazolam · sedation','IV/IO'),find('Midazolam · sedation','IM/IN')],refs:[['SEIZURE · P610',164],['RESTRAINT · P616',174]],note:'Use the row matching the indication and route.'},
 {title:'Ketamine · pain',color:'teal',rows:[find('Ketamine · pain','IV/IO','50 mg/mL'),find('Ketamine · pain','IN','50 mg/mL')],refs:[['PAIN · P611',166]],note:'Age 5+ · 500 mg / 10 mL stock. IN: add 0.1 mL to prime the atomizer.'},
 {title:'TXA',color:'orange',rows:[find('Tranexamic acid')],refs:[['TXA · S506',144]],note:'Use S506 criteria and infusion preparation.'},
 {title:'Bicarb',color:'purple',rows:[find('Sodium bicarbonate')],refs:[['APPENDIX J',237]]}
];
export function pediatricDose(m,i){const amount=m.doses[i];return {amount,unit:m.doseUnits?.[i]??m.unit,volume:amount===null?null:m.volumes?m.volumes[i]:m.unit==='mL'?amount:null,status:amount===null?(m.name==='Ketamine · pain'&&i<4?'TOO YOUNG':'N/A'):null};}
function criticalList(i,source){return `<section class="pediatric-critical" aria-labelledby="critical-title"><div class="section-top"><h2 id="critical-title">CRITICAL MEDICATIONS</h2>${source('APPENDIX J',237)}</div><div class="critical-grid">${criticalGroups.map(g=>{const unavailable=g.rows.every(m=>pediatricDose(m,i).status);return `<article class="critical-card ${unavailable?'unavailable':''}" data-priority="${g.color}" data-critical="${esc(g.title)}"><h3>${g.title}</h3>${g.rows.map(m=>{const d=pediatricDose(m,i);return `<div class="critical-dose ${d.status?'unavailable':''}"><div><b>${esc(m.name.replace('Midazolam · ','').replace('Epinephrine · ','').replace('Ketamine · pain','Pain').replace('Normal saline bolus','Normal saline'))}</b>${routeBadges(m.route)}<small class="critical-concentration">${esc(m.concentration)}</small>${m.dosingRule?`<small class="push-dose-rule">${esc(m.dosingRule)}</small>`:''}</div><div class="critical-value">${d.status?`<b class="dose-unavailable">${d.status}</b>`:`<b>${d.amount} <small>${esc(d.unit)}</small></b>${m.perDose?'<small>per dose</small>':''}${d.volume!==null&&d.unit!=='mL'?`<span>${d.volume} mL</span>`:''}`}</div></div>`;}).join('')}${g.note?`<p>${esc(g.note)}</p>`:''}${g.extraNote?`<p>${esc(g.extraNote)}</p>`:''}<div class="critical-links">${g.refs.map(ref=>source(...ref)).join('')}${g.deviceLink?`<a class="source" href="${g.deviceLink}" target="_blank" rel="noopener">EZ-IO PAIN GUIDE ↗</a>`:''}</div></article>`;}).join('')}</div></section>`;}
export function pediatricUI(state,source,icon){const i=state.age,w=i===null?null:weights[i],energy=energies(i,ZENIX_MAX_ENERGY);const filtered=medications.filter(m=>(m.name+' '+m.route+' '+m.concentration).toLowerCase().includes(state.filter.toLowerCase()));const igels=igelForWeight(w);
 return `<div class="page-heading"><div><div class="eyebrow teal">PEDIATRIC QUICK REFERENCE</div><h1>Small patients. Clear numbers.</h1></div><div class="large-icon teal">${icon('child')}</div></div><section class="panel age-panel"><div class="section-top"><h2>01 <span>Select the reference age</span></h2>${source('Appendix J · pp. 237–238',237)}</div><div class="age-grid">${ages.map((a,n)=>`<button data-age="${n}" class="${i===n?'selected':''}" aria-pressed="${i===n}"><b>${a}</b><span>${weights[n]} kg est.</span></button>`).join('')}</div><p class="calculator-note"><b>Pick the child’s age to pull up the chart weight, airway sizes, shock energy, and doses. These are estimates—check actual weight and confirm the tube with your Broselow tape.</b></p></section>${i===null?'<div class="empty-state">'+icon('child')+'<h2>Choose an age to open its reference card.</h2><p>Airway sizes, shock energy, and critical medications appear first.</p></div>':`
 <div class="pediatric-first"><section class="panel pediatric-airway priority-panel" data-priority="teal"><div class="section-top"><h2>${icon('airway')} Airway sizes</h2></div><div class="airway-sizing"><div><span>ET TUBE · APP J</span><b>${pediatricTubes[i]} <small>mm</small></b></div><div><span>i-gel · ${w} kg ESTIMATE</span><b>${igels.map(s=>s.size).join(' / ')||'N/A'}</b></div></div><p class="clinical-help">${igels.map(s=>`Size ${s.size}: ${s.min}–${s.max} kg`).join(' · ')}. Match actual weight and anatomy.</p><div class="clinical-links">${source('TUBE / BROSELOW · T706',193)}<a class="clinical-reference" href="${igelSource}" target="_blank" rel="noopener">i-gel size guide ↗</a></div></section>
 <section class="panel energy-panel priority-panel" data-priority="orange"><div class="section-top"><h2>${icon('bolt')} Defibrillation</h2>${source('P601',152)}</div><p class="zenix-energy-cap"><b>ZOLL Zenix · 200 J maximum</b></p><div class="energy-grid"><div><span>INITIAL · 2 J/kg</span><b>${energy?energy[0]+' J':'—'}</b></div><div><span>SECOND · 4 J/kg</span><b>${energy?energy[1]+' J':'—'}</b></div><div><span>SUBSEQUENT · 4–10 J/kg</span><b>${energy?(energy[1]===energy[2]?energy[1]:energy[1]+'–'+energy[2])+' J':'—'}</b></div></div><p class="calculator-note"><b>Use the first number for the first shock, the second for the next. Subsequent shocks use the shown range, capped at ${ZENIX_MAX_ENERGY} J for your Zenix.</b></p><p class="clinical-help">Newborn resuscitation: ${source('P600',151)}</p><details><summary>Synchronized cardioversion · PSVT</summary><p>P604: medical-control order required. At ${w} kg estimated weight: ${Math.ceil(w*.5)} J → ${w} J → ${w*2} J. Confirm SYNC before each shock.</p>${source('P604',155)}</details></section></div>
 ${criticalList(i,source)}
 <div class="peds-summary"><section><span>REFERENCE AGE</span><b>${ages[i]}</b></section><section><span>ESTIMATED WEIGHT</span><b>${w} <small>kg</small></b></section><section><span>LOW SYSTOLIC · APP J</span><b>${['60–70','70','70–75','75–80','80','80','85','85','90'][i]} <small>mmHg</small></b></section><section><span>PULSE · APP J</span><b>${['100–180','100–180','90–160','80–140','70–130','70–130','60–120','60–120','60–120'][i]} <small>/min</small></b></section></div>
 <details class="full-medication-reference" data-clinical-open="pediatric-meds" ${state.fields['pediatric-meds-open']?'open':''}><summary><span><b>Medication & fluid reference</b><small>Full table · ${medications.length} entries · search by drug or route</small></span><span class="expand-symbol">+</span></summary><section class="panel medication-panel"><div class="section-top"><h2>Full medication table</h2><label class="search">${icon('search')}<input id="med-search" aria-label="Filter medications" placeholder="Find medication or route…" value="${esc(state.filter)}"></label></div><p class="muted">Verify indication, age limits, repeat dosing, and orders. Table values take precedence. Missing dose: N/A.</p><div class="table-scroll"><table><thead><tr><th>Medication / indication</th><th>Route · concentration</th><th>Dose</th><th>Volume</th></tr></thead><tbody>${filtered.map(m=>{const d=pediatricDose(m,i);return `<tr class="${d.status?'unavailable':''}"><td><b>${m.name}</b>${m.dosingRule?`<small class="push-dose-rule">${esc(m.dosingRule)}</small>`:''}${m.note?`<details><summary>Reference note</summary><p>${m.note}</p></details>`:''}<a class="table-source" href="${protocol}#page=${m.page}" target="_blank" rel="noopener">PROTOCOL · App J ${m.page} ↗</a></td><td>${m.route}<small>${m.concentration}</small></td><td class="dose">${d.status?`<span class="na">${d.status}</span>`:`${d.amount} <small>${esc(d.unit)}</small>${m.perDose?'<br><small>per dose</small>':''}`}</td><td>${d.status?d.status:d.volume!==null?d.volume+' mL':'N/A'}</td></tr>`;}).join('')||'<tr><td colspan="4">No matching medication.</td></tr>'}</tbody></table></div></section></details>`}`;
}
